 + 3*b*mu^3*nu*p*sigma - 3*b*mu^3*nu*sigma + 2*b*mu^3*p*rho*sigma + b*mu^3*p*sigma^2 - b*beta*mu^3*p*sigma - 2*b*mu^3*rho*sigma - b*mu^3*sigma^2 + b*beta*mu^3*sigma + 3*b*mu^2*nu^2*p*sigma - 3*b*mu^2*nu^2*sigma + 5*b*mu^2*nu*p*rho*sigma + 3*b*mu^2*nu*p*sigma^2 - 3*b*beta*mu^2*nu*p*sigma - 5*b*mu^2*nu*rho*sigma - 3*b*mu^2*nu*sigma^2 + 3*b*beta*mu^2*nu*sigma + b*mu^2*p*rho^2*sigma + b*mu^2*p*rho*sigma^2 - b*beta*mu^2*p*rho*sigma - b*beta*mu^2*p*sigma^2 - b*mu^2*rho^2*sigma - b*mu^2*rho*sigma^2 + b*beta*mu^2*rho*sigma + b*beta*mu^2*sigma^2 + b*mu*nu^3*p*sigma - b*mu*nu^3*sigma + 4*b*mu*nu^2*p*rho*sigma + 3*b*mu*nu^2*p*sigma^2 - 3*b*beta*mu*nu^2*p*sigma - 4*b*mu*nu^2*rho*sigma - 3*b*mu*nu^2*sigma^2 + 3*b*beta*mu*nu^2*sigma + 2*b*mu*nu*p*rho^2*sigma + 2*b*mu*nu*p*rho*sigma^2 - 2*b*beta*mu*nu*p*rho*sigma - 2*b*beta*mu*nu*p*sigma^2 - 2*b*mu*nu*rho^2*sigma - 2*b*mu*nu*rho*sigma^2 + 2*b*beta*mu*nu*rho*sigma + 2*b*beta*mu*nu*sigma^2 - b*beta*mu*p^2*rho*sigma^2 + b*beta*mu*p*rho*sigma^2 + b*nu^3*p*rho*sigma + b*nu^3*p*sigma^2 - b*beta*nu^3*p*sigma - b*nu^3*rho*sigma - b*nu^3*sigma^2 + b*beta*nu^3*sigma + b*nu^2*p*rho^2*sigma + b*nu^2*p*rho*sigma^2 - b*beta*nu^2*p*rho*sigma - b*beta*nu^2*p*sigma^2 - b*nu^2*rho^2*sigma - b*nu^2*rho*sigma^2 + b*beta*nu^2*rho*sigma + b*beta*nu^2*sigma^2 - b*beta*nu*p^2*rho*sigma^2 + b*beta*nu*p*rho*sigma^2)/(beta*gamma0^2*mu^3 + 2*beta*gamma0^2*mu^2*nu - 2*beta*gamma0^2*mu^2*p*sigma + 2*beta*gamma0^2*mu^2*rho + 2*beta*gamma0^2*mu^2*sigma + beta*gamma0^2*mu*nu^2 - 2*beta*gamma0^2*mu*nu*p*sigma + 2*beta*gamma0^2*mu*nu*rho + 2*beta*gamma0^2*mu*nu*sigma + beta*gamma0^2*mu*p^2*sigma^2 - 2*beta*gamma0^2*mu*p*rho*sigma - 2*beta*gamma0^2*mu*p*sigma^2 + beta*gamma0^2*mu*rho^2 + 2*beta*gamma0^2*mu*rho*sigma + beta*gamma0^2*mu*sigma^2 + 2*beta*gamma0*mu^4 + 6*beta*gamma0*mu^3*nu - 2*beta*gamma0*mu^3*p*sigma + 4*beta*gamma0*mu^3*rho + 4*beta*gamma0*mu^3*sigma + 6*beta*gamma0*mu^2*nu^2 - 4*beta*gamma0*mu^2*nu*p*sigma + 8*beta*gamma0*mu^2*nu*rho + 8*beta*gamma0*mu^2*nu*sigma - 2*beta*gamma0*mu^2*p*sigma^2 + 2*beta*gamma0*mu^2*rho^2 + 4*beta*gamma0*mu^2*rho*sigma + 2*beta*gamma0*mu^2*sigma^2 + 2*beta*gamma0*mu*nu^3 - 2*beta*gamma0*mu*nu^2*p*sigma + 4*beta*gamma0*mu*nu^2*rho + 4*beta*gamma0*mu*nu^2*sigma - 2*beta*gamma0*mu*nu*p*sigma^2 + 2*beta*gamma0*mu*nu*rho^2 + 4*beta*gamma0*mu*nu*rho*sigma + 2*beta*gamma0*mu*nu*sigma^2 - 2*beta*gamma0*mu*p^2*rho*sigma^2 + 2*beta*gamma0*mu*p*rho^2*sigma + 2*beta*gamma0*mu*p*rho*sigma^2 + beta*mu^5 + 4*beta*mu^4*nu + 2*beta*mu^4*rho + 2*beta*mu^4*sigma + 6*beta*mu^3*nu^2 + 6*beta*mu^3*nu*rho + 6*beta*mu^3*nu*sigma + 2*beta*mu^3*p*rho*sigma + beta*mu^3*rho^2 + 2*beta*mu^3*rho*sigma + beta*mu^3*sigma^2 + 4*beta*mu^2*nu^3 + 6*beta*mu^2*nu^2*rho + 6*beta*mu^2*nu^2*sigma + 4*beta*mu^2*nu*p*rho*sigma + 2*beta*mu^2*nu*rho^2 + 4*beta*mu^2*nu*rho*sigma + 2*beta*mu^2*nu*sigma^2 + 2*beta*mu^2*p*rho^2*sigma + 2*beta*mu^2*p*rho*sigma^2 + beta*mu*nu^4 + 2*beta*mu*nu^3*rho + 2*beta*mu*nu^3*sigma + 2*beta*mu*nu^2*p*rho*sigma + beta*mu*nu^2*rho^2 + 2*beta*mu*nu^2*rho*sigma + beta*mu*nu^2*sigma^2 + 2*beta*mu*nu*p*rho^2*sigma + 2*beta*mu*nu*p*rho*sigma^2 + beta*mu*p^2*rho^2*sigma^2)
ISmat = -(p*(mu + nu + rho)*(b*mu^3*sigma + b*mu^2*sigma^2 + b*nu^2*sigma^2 - b*beta*gamma0*sigma^2 - b*beta*mu*sigma^2 - b*beta*mu^2*sigma - b*beta*nu*sigma^2 - b*beta*nu^2*sigma + b*gamma0*mu*sigma^2 + b*gamma0*mu^2*sigma + b*gamma0*nu*sigma^2 + b*gamma0*rho*sigma^2 + b*gamma0*rho^2*sigma + 2*b*mu*nu*sigma^2 + b*mu*nu^2*sigma + 2*b*mu^2*nu*sigma + b*mu*rho*sigma^2 + b*mu*rho^2*sigma + 2*b*mu^2*rho*sigma + b*nu*rho*sigma^2 + b*nu*rho^2*sigma + b*nu^2*rho*sigma - b*beta*gamma0*mu*sigma - b*beta*gamma0*nu*sigma - b*beta*gamma0*rho*sigma - 2*b*beta*mu*nu*sigma - b*beta*mu*rho*sigma - b*beta*nu*rho*sigma + b*gamma0*mu*nu*sigma + 2*b*gamma0*mu*rho*sigma + b*gamma0*nu*rho*sigma + 3*b*mu*nu*rho*sigma + b*beta*gamma0*p*sigma^2 - b*beta*p*rho*sigma^2))/(beta*gamma0^2*mu^3 + 2*beta*gamma0^2*mu^2*nu - 2*beta*gamma0^2*mu^2*p*sigma + 2*beta*gamma0^2*mu^2*rho + 2*beta*gamma0^2*mu^2*sigma + beta*gamma0^2*mu*nu^2 - 2*beta*gamma0^2*mu*nu*p*sigma + 2*beta*gamma0^2*mu*nu*rho + 2*beta*gamma0^2*mu*nu*sigma + beta*gamma0^2*mu*p^2*sigma^2 - 2*beta*gamma0^2*mu*p*rho*sigma - 2*beta*gamma0^2*mu*p*sigma^2 + beta*gamma0^2*mu*rho^2 + 2*beta*gamma0^2*mu*rho*sigma + beta*gamma0^2*mu*sigma^2 + 2*beta*gamma0*mu^4 + 6*beta*gamma0*mu^3*nu - 2*beta*gamma0*mu^3*p*sigma + 4*beta*gamma0*mu^3*rho + 4*beta*gamma0*mu^3*sigma + 6*beta*gamma0*mu^2*nu^2 - 4*beta*gamma0*mu^2*nu*p*sigma + 8*beta*gamma0*mu^2*nu*rho + 8*beta*gamma0*mu^2*nu*sigma - 2*beta*gamma0*mu^2*p*sigma^2 + 2*beta*gamma0*mu^2*rho^2 + 4*beta*gamma0*mu^2*rho*sigma + 2*beta*gamma0*mu^2*sigma^2 + 2*beta*gamma0*mu*nu^3 - 2*beta*gamma0*mu*nu^2*p*sigma + 4*beta*gamma0*mu*nu^2*rho + 4*beta*gamma0*mu*nu^2*sigma - 2*beta*gamma0*mu*nu*p*sigma^2 + 2*beta*gamma0*mu*nu*rho^2 + 4*beta*gamma0*mu*nu*rho*sigma + 2*beta*gamma0*mu*nu*sigma^2 - 2*beta*gamma0*mu*p^2*rho*sigma^2 + 2*beta*gamma0*mu*p*rho^2*sigma + 2*beta*gamma0*mu*p*rho*sigma^2 + beta*mu^5 + 4*beta*mu^4*nu + 2*beta*mu^4*rho + 2*beta*mu^4*sigma + 6*beta*mu^3*nu^2 + 6*beta*mu^3*nu*rho + 6*beta*mu^3*nu*sigma + 2*beta*mu^3*p*rho*sigma + beta*mu^3*rho^2 + 2*beta*mu^3*rho*sigma + beta*mu^3*sigma^2 + 4*beta*mu^2*nu^3 + 6*beta*mu^2*nu^2*rho + 6*beta*mu^2*nu^2*sigma + 4*beta*mu^2*nu*p*rho*sigma + 2*beta*mu^2*nu*rho^2 + 4*beta*mu^2*nu*rho*sigma + 2*beta*mu^2*nu*sigma^2 + 2*beta*mu^2*p*rho^2*sigma + 2*beta*mu^2*p*rho*sigma^2 + beta*mu*nu^4 + 2*beta*mu*nu^3*rho + 2*beta*mu*nu^3*sigma + 2*beta*mu*nu^2*p*rho*sigma + beta*mu*nu^2*rho^2 + 2*beta*mu*nu^2*rho*sigma + beta*mu*nu^2*sigma^2 + 2*beta*mu*nu*p*rho^2*sigma + 2*beta*mu*nu*p*rho*sigma^2 + beta*mu*p^2*rho^2*sigma^2)
%lambdamat = beta*simplify(1-Smat*mu/b);
lambdamat = -(gamma0*mu^2 - beta*nu^2 - beta*mu^2 + gamma0*rho^2 + mu*nu^2 + 2*mu^2*nu + mu*rho^2 + 2*mu^2*rho + nu*rho^2 + nu^2*rho + mu^2*sigma + nu^2*sigma + mu^3 - beta*gamma0*mu - beta*gamma0*nu - beta*gamma0*rho - beta*gamma0*sigma - 2*beta*mu*nu - beta*mu*rho - beta*nu*rho - beta*mu*sigma + gamma0*mu*nu - beta*nu*sigma + 2*gamma0*mu*rho + gamma0*nu*rho + gamma0*mu*sigma + gamma0*nu*sigma + gamma0*rho*sigma + 3*mu*nu*rho + 2*mu*nu*sigma + mu*rho*sigma + nu*rho*sigma + beta*gamma0*p*sigma - beta*p*rho*sigma)/(gamma0*mu + gamma0*nu + gamma0*rho + gamma0*sigma + 2*mu*nu + mu*rho + nu*rho + mu*sigma + nu*sigma + mu^2 + nu^2 - gamma0*p*sigma + p*rho*sigma)

Rp_cal = beta.*((nu+rho+mu+sigma).*(gamma0+nu+mu)-sigma*p*(gamma0-rho))./((mu+sigma+rho).*(gamma0 + mu + nu).*(mu + nu + rho));
Pasympt = (Emat+IAmat)/(b/mu);
Pasympt_cal = lambdamat*(nu+rho+mu+(1-p)*sigma)/(Rp_cal*(sigma+rho+mu)*(nu+rho+mu))

simplify(Pasympt-Pasympt_cal)

Scal = b/(mu.*Rp_cal)
simplify(Smat-Scal)

lambda = beta*(1-1/Rp_cal);
simplify(lambda-lambdamat)

%% Case lambda = beta*(IA)/N;
clear all
syms b lambda beta p sigma gamma0 rho mu nu S E IS IA ; N = b/mu;
Smat = -(b*(mu + nu + rho)*(mu + rho + sigma))/(beta*mu*sigma*(p - 1))
Emat = (b*(gamma0 + mu + nu)*(mu + nu + rho)*(mu*nu - beta*sigma + 2*mu*rho + nu*rho + mu*sigma + nu*sigma + rho*sigma + mu^2 + rho^2 + beta*p*sigma))/(beta*mu*sigma*(p - 1)*(gamma0*mu + gamma0*nu + gamma0*rho + gamma0*sigma + 2*mu*nu + mu*rho + nu*rho + mu*sigma + nu*sigma + mu^2 + nu^2 - gamma0*p*sigma + p*rho*sigma))
IAmat = -(b*(gamma0 + mu + nu)*(mu*nu - beta*sigma + 2*mu*rho + nu*rho + mu*sigma + nu*sigma + rho*sigma + mu^2 + rho^2 + beta*p*sigma))/(beta*mu*(gamma0*mu + gamma0*nu + gamma0*rho + gamma0*sigma + 2*mu*nu + mu*rho + nu*rho + mu*sigma + nu*sigma + mu^2 + nu^2 - gamma0*p*sigma + p*rho*sigma))
ISmat = (b*p*(mu + nu + rho)*(mu*nu - beta*sigma + 2*mu*rho + nu*rho + mu*sigma + nu*sigma + rho*sigma + mu^2 + rho^2 + beta*p*sigma))/(beta*mu*(p - 1)*(gamma0*mu + gamma0*nu + gamma0*rho + gamma0*sigma + 2*mu*nu + mu*rho + nu*rho + mu*sigma + nu*sigma + mu^2 + nu^2 - gamma0*p*sigma + p*rho*sigma))
Rp = beta*(1-p)*sigma./((sigma+rho+mu).*(nu+rho+mu));%ok
Scal = b./(mu*Rp); %ok
lambdamat = beta*IAmat/(b/mu);

%Pasympt_cal = lambdamat*(nu+rho+mu+(1-p)*sigma)/(Rp*(sigma+rho+mu)*(nu+rho+mu))
Pasympt_cal2 = lambdamat*(nu+rho+mu+(1-p)*sigma)/(beta*(1-p)*sigma)
simplify(Pasympt_cal2-Pasympt_cal2)

Pasympt_mat = (E+IA)/N;
simplify(Pasympt_cal2 - Pasympt_mat)

lambda = (Rp-1)/Rp*beta*(1-p)*sigma*(gamma0+nu+mu)/((nu+rho+mu)*(gamma0+nu+mu)+sigma*(gamma0*(1-p)+nu+p*rho+mu));%ok
simplify(lambda-lambdamat)

%% Case lambda = beta*(E+IA)/N;
clear all
